package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_KEY;
import static com.android.SdkConstants.ATTR_RESTRICTION_TYPE;
import static com.android.SdkConstants.TAG_RESTRICTION;
import static com.android.SdkConstants.TAG_RESTRICTIONS;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.google.common.collect.ImmutableSet;
import java.util.Arrays;
import java.util.Collection;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class RestrictionsDetector extends Detector implements XmlScanner {
    public static final String TAG_RESTRICTIONS = "restrictions";
    public static final String TAG_RESTRICTION = "restriction";
    public static final String ATTR_KEY = "key";
    public static final String ATTR_TYPE = "restrictionType";
    public static final int MAX_NESTING_DEPTH = 2;
    public static final int MAX_NUMBER_OF_NESTED_RESTRICTIONS = 100;
    private static final Collection<String> VALID_TYPES =
            ImmutableSet.of("bool", "string", "integer", "choice", "hidden", "bundle", "bundle_array");

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.XML;
    }

    @NonNull
    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_RESTRICTIONS, TAG_RESTRICTION);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String tag = element.getTagName();
        if (tag.equals(TAG_RESTRICTIONS)) {
            if (element.getParentNode().getNodeType() != Node.DOCUMENT_NODE) {
                context.report(ISSUE, element, context.getLocation(element),
                        "The <restrictions> tag must be the root element");
            }
            for (Element child : Lint.getChildren(element)) {
                if (!child.getTagName().equals(TAG_RESTRICTION)) {
                    context.report(ISSUE, child, context.getLocation(child),
                            "The <restrictions> tag can only contain <restriction> elements");
                }
            }
        } else if (tag.equals(TAG_RESTRICTION)) {
            String key = element.getAttributeNS(ANDROID_URI, ATTR_KEY);
            if (key.isEmpty()) {
                context.report(ISSUE, element, context.getLocation(element),
                        "The <restriction> tag must specify a key attribute");
            }
            String type = element.getAttributeNS(ANDROID_URI, ATTR_TYPE);
            if (type.isEmpty()) {
                context.report(ISSUE, element, context.getLocation(element),
                        "The <restriction> tag must specify a restrictionType attribute");
            } else if (!VALID_TYPES.contains(type)) {
                context.report(ISSUE, element, context.getLocation(element),
                        String.format("Invalid restriction type: %s", type));
            } else if (type.equals("bundle") || type.equals("bundle_array")) {
                int count = 0;
                for (Element child : Lint.getChildren(element)) {
                    if (!child.getTagName().equals(TAG_RESTRICTION)) {
                        context.report(ISSUE, child, context.getLocation(child),
                                String.format("A %s restriction can only contain <restriction> elements", type));
                    } else {
                        count++;
                    }
                }
                if (count > MAX_NUMBER_OF_NESTED_RESTRICTIONS) {
                    context.report(ISSUE, element, context.getLocation(element),
                            String.format("A %s restriction can contain at most %d nested restrictions", type, MAX_NUMBER_OF_NESTED_RESTRICTIONS));
                }
                int depth = getDepth(element);
                if (depth > MAX_NESTING_DEPTH) {
                    context.report(ISSUE, element, context.getLocation(element),
                            String.format("Restrictions can only be nested up to %d levels deep", MAX_NESTING_DEPTH));
                }
            }
        }
    }

    private static int getDepth(Element element) {
        int depth = 0;
        Node node = element;
        while (node != null) {
            if (node.getNodeType() == Node.ELEMENT_NODE && ((Element) node).getTagName().equals(TAG_RESTRICTION)) {
                depth++;
            }
            node = node.getParentNode();
        }
        return depth;
    }
}
```

