```
private void validateNestedRestrictions(XmlContext context, Element element, String restrictionType) {
    int count = 0;
    for (Node child = element.getFirstChild(); child != null; child = child.getNextSibling()) {
        if (child.getNodeType() == Node.ELEMENT_NODE) {
            Element childElement = (Element) child;
            if (!TAG_RESTRICTION.equals(childElement.getTagName())) {
                context.report(..., "A " + restrictionType + " restriction can only contain <restriction> elements");
                continue;
            }
            count++;
            if (restrictionType.equals(TYPE_BUNDLE_ARRAY)) {
                String childType = childElement.getAttribute(ANDROID_URI, ATTR_RESTRICTION_TYPE);
                if (childType != null && !childType.isEmpty() && !TYPE_BUNDLE.equals(childType)) {
                    context.report(..., "bundle_array restrictions can only contain bundle restrictions");
                }
            }
        }
    }
    if (count == 0) {
        context.report(..., "A " + restrictionType + " restriction must contain at least one nested restriction");
    } else if (count > MAX_NUMBER_OF_NESTED_RESTRICTIONS) {
        context.report(..., "A " + restrictionType + " restriction can contain at most " + MAX_NUMBER_OF_NESTED_RESTRICTIONS + " nested restrictions");
    }
    if (getRestrictionDepth(element) > MAX_NESTING_DEPTH) {
        context.report(..., "Restrictions can only be nested up to " + MAX_NESTING_DEPTH + " levels deep");
    }
}
